// ─── Report export helpers ────────────────────────────────────────────────────
// One place for CSV / Excel / PDF export so every report exports identically.

const fmtCell = (value, type) => {
  if (value === null || value === undefined || value === '') return '';
  if (type === 'money') return Number(value).toFixed(2);
  if (type === 'number') return String(Number(value));
  if (type === 'date') {
    const d = new Date(value);
    return Number.isNaN(d.getTime()) ? String(value) : d.toISOString().slice(0, 10);
  }
  return String(value);
};

const buildMatrix = (report) => {
  const headers = report.columns.map((c) => c.label);
  const body = report.rows.map((row) => report.columns.map((c) => fmtCell(row[c.key], c.type)));
  const hasTotals = Object.keys(report.totals || {}).length > 0;
  const totalsRow = hasTotals
    ? report.columns.map((c, i) => {
        if (i === 0) return 'TOTAL';
        const t = report.totals[c.key];
        return t === undefined ? '' : fmtCell(t, c.type);
      })
    : null;
  return { headers, body, totalsRow };
};

const fileBase = (report) =>
  `${report.meta.title.replace(/[^a-z0-9]+/gi, '-').toLowerCase()}-${report.meta.from}-to-${report.meta.to}`;

const triggerDownload = (blob, filename) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

// ── CSV ──────────────────────────────────────────────────────────────────────
const escapeCsv = (v) => {
  const s = String(v ?? '');
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export const exportCsv = (report) => {
  const { headers, body, totalsRow } = buildMatrix(report);
  const lines = [
    [report.meta.title],
    [`Period: ${report.meta.from} to ${report.meta.to}`],
    [`Module: ${report.meta.module}`],
    [`Generated: ${new Date(report.meta.generated_at).toLocaleString()}`],
    [],
    headers,
    ...body,
    ...(totalsRow ? [totalsRow] : []),
  ];
  const csv = lines.map((r) => (Array.isArray(r) ? r.map(escapeCsv).join(',') : escapeCsv(r))).join('\r\n');
  triggerDownload(new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' }), `${fileBase(report)}.csv`);
};

// ── Excel (real .xlsx via SheetJS) ───────────────────────────────────────────
export const exportExcel = async (report) => {
  const XLSX = await import('xlsx');
  const { headers, body, totalsRow } = buildMatrix(report);

  const summaryRows = Object.entries(report.summary || {}).map(([k, v]) => [
    k.replace(/_/g, ' ').replace(/\b\w/g, (m) => m.toUpperCase()),
    v,
  ]);

  const aoa = [
    [report.meta.title],
    [`Period: ${report.meta.from} to ${report.meta.to}`],
    [`Module: ${report.meta.module}`],
    [`Generated: ${new Date(report.meta.generated_at).toLocaleString()}`],
    [],
    ['SUMMARY'],
    ...summaryRows,
    [],
    headers,
    ...body,
    ...(totalsRow ? [totalsRow] : []),
  ];

  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws['!cols'] = headers.map((h) => ({ wch: Math.max(14, String(h).length + 2) }));
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Report');
  XLSX.writeFile(wb, `${fileBase(report)}.xlsx`);
};

// ── PDF (jsPDF + autotable: header, summary, table, page numbers, timestamp) ──
export const exportPdf = async (report, { companyName = 'Delivery Suite', vendorInfo = '', generatedBy = '' } = {}) => {
  const { jsPDF } = await import('jspdf');
  // v3 attaches itself to jsPDF as a plugin (doc.autoTable), so this import is
  // for its side effect rather than a standalone export.
  await import('jspdf-autotable');

  const doc = new jsPDF({ orientation: 'landscape', unit: 'pt', format: 'a4' });
  const pageWidth = doc.internal.pageSize.getWidth();
  const { headers, body, totalsRow } = buildMatrix(report);

  // Header band
  doc.setFillColor(37, 99, 235);
  doc.rect(0, 0, pageWidth, 60, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(16);
  doc.text(companyName, 40, 27);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  if (vendorInfo) doc.text(vendorInfo, 40, 44);
  doc.setFontSize(13);
  doc.setFont('helvetica', 'bold');
  doc.text(report.meta.title, pageWidth - 40, 30, { align: 'right' });
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.text(`${report.meta.from}  to  ${report.meta.to}`, pageWidth - 40, 46, { align: 'right' });

  doc.setTextColor(30, 41, 59);
  doc.setFontSize(9);
  const metaLine = [
    `Module: ${report.meta.module}`,
    generatedBy ? `Generated by: ${generatedBy}` : null,
    `Generated: ${new Date(report.meta.generated_at).toLocaleString()}`,
    `Records: ${report.meta.row_count}`,
  ].filter(Boolean).join('     |     ');
  doc.text(metaLine, 40, 78);

  // Summary grid
  const summaryEntries = Object.entries(report.summary || {});
  if (summaryEntries.length) {
    doc.autoTable({
      startY: 90,
      head: [['Summary', 'Value']],
      body: summaryEntries.map(([k, v]) => [
        k.replace(/_/g, ' ').replace(/\b\w/g, (m) => m.toUpperCase()),
        typeof v === 'number' ? v.toLocaleString(undefined, { maximumFractionDigits: 2 }) : String(v),
      ]),
      theme: 'grid',
      styles: { fontSize: 8, cellPadding: 4 },
      headStyles: { fillColor: [30, 41, 59], textColor: 255 },
      tableWidth: 280,
    });
  }

  // Detail table
  doc.autoTable({
    startY: (doc.lastAutoTable?.finalY || 90) + 16,
    head: [headers],
    body: totalsRow ? [...body, totalsRow] : body,
    theme: 'striped',
    styles: { fontSize: 8, cellPadding: 4, overflow: 'linebreak' },
    headStyles: { fillColor: [37, 99, 235], textColor: 255, fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [246, 249, 252] },
    didParseCell: (data) => {
      // Bold the trailing TOTAL row
      if (totalsRow && data.section === 'body' && data.row.index === body.length) {
        data.cell.styles.fontStyle = 'bold';
        data.cell.styles.fillColor = [226, 232, 240];
      }
    },
  });

  // Footer with page numbers on every page
  const pages = doc.internal.getNumberOfPages();
  const pageHeight = doc.internal.pageSize.getHeight();
  for (let i = 1; i <= pages; i += 1) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(100, 116, 139);
    doc.text(`${companyName} — ${report.meta.title}`, 40, pageHeight - 20);
    doc.text(`Page ${i} of ${pages}`, pageWidth - 40, pageHeight - 20, { align: 'right' });
    doc.text(
      `Generated ${new Date(report.meta.generated_at).toLocaleString()}`,
      pageWidth / 2, pageHeight - 20, { align: 'center' }
    );
  }

  doc.save(`${fileBase(report)}.pdf`);
};

export const printReport = () => window.print();
